1: //! Station interior floor — the tile map a station's inside is built from.
2: //!
3: //! **Hot-path note**: per-frame queries (`tile_at`, `width`, `height`) read from
4: //! the decoded `grid` cache (a `TileGrid<TileKind>`), not from the authored glyph
5: //! strings.
6: 
7: use crate::tilegrid::TileGrid;
8: use crate::TileKind;
9: 
10: pub struct Floor {
11:     /// Decoded tile cache backing the per-frame `tile_at` lookup.
12:     grid: TileGrid<TileKind>,
13: }
14: 
15: impl Floor {
16:     pub fn new(w: u32, h: u32, tiles: Vec<TileKind>) -> Self {
17:         assert_eq!(tiles.len(), (w * h) as usize, "tile count must match dims");
18:         let mut grid = TileGrid::new_filled(w, h, TileKind::Empty);
19:         for (i, t) in tiles.into_iter().enumerate() {
20:             let (c, r) = ((i as u32 % w) as i32, (i as u32 / w) as i32);
21:             grid.set(c, r, t);
22:         }
23:         Floor { grid }
24:     }
25: 
26:     pub fn width(&self) -> u32 {
27:         self.grid.width()
28:     }
29: 
30:     pub fn height(&self) -> u32 {
31:         self.grid.height()
32:     }
33: 
34:     /// Tile at `(col, row)`; out-of-bounds reads as `Empty`.
35:     pub fn tile_at(&self, col: i32, row: i32) -> TileKind {
36:         self.grid.tile_at(col, row)
37:     }
38: 
39:     /// Group contiguous tiles of one `kind` into rectangular regions via a
40:     /// 4-connected flood-fill, returning each region's top-left anchor and tile
41:     /// size. The single grouping primitive behind every multi-tile derivation —
42:     /// elevator cars, apartment doors, dock-pad synthesis.
43:     pub fn tile_regions(&self, kind: TileKind) -> Vec<([u32; 2], [u32; 2])> {
44:         let w = self.width() as i32;
45:         let h = self.height() as i32;
46:         let mut visited = vec![false; (w.max(0) * h.max(0)) as usize];
47:         let idx = |c: i32, r: i32| (r * w + c) as usize;
48:         let mut out = Vec::new();
49:         for r0 in 0..h {
50:             for c0 in 0..w {
51:                 if visited[idx(c0, r0)] || self.tile_at(c0, r0) != kind {
52:                     continue;
53:                 }
54:                 let mut stack = vec![(c0, r0)];
55:                 let (mut min_c, mut max_c, mut min_r, mut max_r) = (c0, c0, r0, r0);
56:                 while let Some((c, r)) = stack.pop() {
57:                     if c < 0 || r < 0 || c >= w || r >= h || visited[idx(c, r)] {
58:                         continue;
59:                     }
60:                     if self.tile_at(c, r) != kind {
61:                         continue;
62:                     }
63:                     visited[idx(c, r)] = true;
64:                     min_c = min_c.min(c);
65:                     max_c = max_c.max(c);
66:                     min_r = min_r.min(r);
67:                     max_r = max_r.max(r);
68:                     stack.push((c + 1, r));
69:                     stack.push((c - 1, r));
70:                     stack.push((c, r + 1));
71:                     stack.push((c, r - 1));
72:                 }
73:                 out.push((
74:                     [min_c as u32, min_r as u32],
75:                     [(max_c - min_c + 1) as u32, (max_r - min_r + 1) as u32],
76:                 ));
77:             }
78:         }
79:         out
80:     }
81: 
82:     /// First tile of the given `kind` in row-major scan order, as `(col, row)`.
83:     /// `None` if the floor has no such tile.
84:     pub fn find_first(&self, kind: TileKind) -> Option<(u32, u32)> {
85:         for row in 0..self.height() {
86:             for col in 0..self.width() {
87:                 if self.tile_at(col as i32, row as i32) == kind {
88:                     return Some((col, row));
89:                 }
90:             }
91:         }
92:         None
93:     }
94: }

